// Renders assets/telemetry.svg: a Project Reborn styled console built from the real
// GitHub contribution calendar. No npm packages; text is drawn from glyphs.json
// (generated by assets/src/build.py) because README images cannot load web fonts.
//
//   node .github/scripts/telemetry.mjs --out assets/telemetry.svg
//   node .github/scripts/telemetry.mjs --placeholder --out assets/telemetry.svg
//   node .github/scripts/telemetry.mjs --input calendar.json --out preview.svg
//
// Data: GraphQL contributionCalendar (GITHUB_TOKEN), falling back to the public
// contributions page. If neither answers, the script exits non-zero and the
// previous SVG stays in place, so nothing is ever invented.

import fs from 'node:fs';

const args = process.argv.slice(2);
const opt = (name, fallback = null) => {
  const i = args.indexOf(name);
  return i === -1 ? fallback : args[i + 1];
};
const LOGIN = process.env.GH_LOGIN || 'StigmaAU';
const TZ = 'Australia/Brisbane';
const OUT = opt('--out', 'assets/telemetry.svg');

const atlas = JSON.parse(fs.readFileSync(new URL('./glyphs.json', import.meta.url), 'utf8'));
const C = {
  card: '#111015', panel: '#18171d', line: '#2f2f36', ink: '#f3f2f6', muted: '#a8a6b3', subtle: '#8f8d9b',
  purple: '#a219ff', purpleInk: '#c895ff', purpleSoft: '#2e1a45', cyan: '#5be4ff',
};
const LEVELS = ['#1d1c23', '#3a1c62', '#5d23a6', '#8a1fe0', '#c895ff'];
const MONTHS = ['JAN', 'FEB', 'MAR', 'APR', 'MAY', 'JUN', 'JUL', 'AUG', 'SEP', 'OCT', 'NOV', 'DEC'];
const DAYS = ['Sundays', 'Mondays', 'Tuesdays', 'Wednesdays', 'Thursdays', 'Fridays', 'Saturdays'];

// ------------------------------------------------------------------ data --

async function fromGraphQL(token) {
  const query = `query($login:String!){user(login:$login){contributionsCollection{contributionCalendar{
    totalContributions weeks{contributionDays{date contributionCount}}}}}}`;
  const res = await fetch('https://api.github.com/graphql', {
    method: 'POST',
    headers: { Authorization: `bearer ${token}`, 'Content-Type': 'application/json', 'User-Agent': 'stigmaau-telemetry' },
    body: JSON.stringify({ query, variables: { login: LOGIN } }),
  });
  const json = await res.json();
  const cal = json?.data?.user?.contributionsCollection?.contributionCalendar;
  if (!res.ok || !cal) throw new Error(`GraphQL: ${res.status} ${JSON.stringify(json.errors || json.message || '')}`);
  return cal.weeks.flatMap(w => w.contributionDays.map(d => ({ date: d.date, count: d.contributionCount })));
}

async function fromProfilePage() {
  const res = await fetch(`https://github.com/users/${LOGIN}/contributions`, {
    headers: { 'User-Agent': 'stigmaau-telemetry', Accept: 'text/html' },
  });
  if (!res.ok) throw new Error(`contributions page: ${res.status}`);
  const html = await res.text();
  const ids = new Map();
  for (const m of html.matchAll(/<td[^>]*?data-date="(\d{4}-\d{2}-\d{2})"[^>]*?id="([^"]+)"/g)) ids.set(m[2], m[1]);
  for (const m of html.matchAll(/<td[^>]*?id="([^"]+)"[^>]*?data-date="(\d{4}-\d{2}-\d{2})"/g)) ids.set(m[1], m[2]);
  const days = new Map([...ids.values()].map(d => [d, 0]));
  for (const m of html.matchAll(/<tool-tip[^>]*?for="([^"]+)"[^>]*>([^<]*)<\/tool-tip>/g)) {
    const date = ids.get(m[1]);
    const n = m[2].match(/^(\d[\d,]*) contribution/);
    if (date) days.set(date, n ? Number(n[1].replace(/,/g, '')) : 0);
  }
  if (days.size < 300) throw new Error(`contributions page: only ${days.size} days parsed`);
  return [...days].map(([date, count]) => ({ date, count })).sort((a, b) => a.date.localeCompare(b.date));
}

async function loadDays() {
  const input = opt('--input');
  if (input) return JSON.parse(fs.readFileSync(input, 'utf8'));
  const token = process.env.GITHUB_TOKEN;
  if (token) {
    try { return await fromGraphQL(token); } catch (e) { console.warn(e.message, '- trying the profile page'); }
  }
  return fromProfilePage();
}

const isoToday = () => new Intl.DateTimeFormat('en-CA', { timeZone: TZ }).format(new Date());

function stats(days, today) {
  const from = new Date(`${today}T00:00:00Z`);
  from.setUTCDate(from.getUTCDate() - 364);
  const since = from.toISOString().slice(0, 10);
  const upto = days.filter(d => d.date <= today && d.date >= since); // rolling 365 days
  const total = upto.reduce((s, d) => s + d.count, 0);
  const active = upto.filter(d => d.count > 0).length;
  let longest = 0, run = 0;
  for (const d of upto) { run = d.count > 0 ? run + 1 : 0; longest = Math.max(longest, run); }
  // a streak is still alive if today has nothing yet but yesterday did
  let i = upto.length - 1, current = 0;
  if (i >= 0 && upto[i].count === 0) i--;
  for (; i >= 0 && upto[i].count > 0; i--) current++;
  const peak = upto.reduce((a, d) => (d.count > a.count ? d : a), { count: 0, date: null });
  const byDay = Array(7).fill(0);
  for (const d of upto) byDay[new Date(`${d.date}T00:00:00Z`).getUTCDay()] += d.count;
  const topDay = byDay.indexOf(Math.max(...byDay));
  const nonzero = upto.map(d => d.count).filter(Boolean).sort((a, b) => a - b);
  const q = p => nonzero[Math.min(nonzero.length - 1, Math.floor(p * nonzero.length))] || 1;
  return { total, active, span: upto.length, longest, current, peak, topDay: total ? topDay : null, cuts: [q(0.25), q(0.5), q(0.75)] };
}

// -------------------------------------------------------------- drawing --

class Doc {
  constructor(w, h) { Object.assign(this, { w, h, defs: [], body: [], used: new Map() }); }
  measure(text, key, size, ls = 0) {
    const f = atlas.fonts[key];
    const adv = [...text].reduce((s, ch) => s + glyph(f, ch)[0], 0) + ls * f.upm * Math.max(text.length - 1, 0);
    return adv * size / f.upm;
  }
  text(text, x, y, key, size, { fill = C.ink, anchor = 'start', ls = 0, cls = '' } = {}) {
    const f = atlas.fonts[key];
    const k = size / f.upm;
    const w = this.measure(text, key, size, ls);
    if (anchor === 'middle') x -= w / 2;
    if (anchor === 'end') x -= w;
    let pen = 0, uses = '';
    for (const ch of text) {
      const [adv, d] = glyph(f, ch);
      if (d) uses += `<use href="#${this.id(key, ch, d)}"${pen ? ` x="${Math.round(pen)}"` : ''}/>`;
      pen += adv + ls * f.upm;
    }
    return `<g transform="translate(${n(x)} ${n(y)}) scale(${k.toPrecision(5)})" fill="${fill}"${cls ? ` class="${cls}"` : ''}>${uses}</g>`;
  }
  id(key, ch, d) {
    const k = key + ch;
    if (!this.used.has(k)) {
      const id = `${key}${this.used.size.toString(36)}`;
      this.used.set(k, id);
      this.defs.push(`<path id="${id}" d="${d}"/>`);
    }
    return this.used.get(k);
  }
}

const glyph = (f, ch) => f.glyphs[ch] || f.glyphs['?'];
const n = v => String(Math.round(v * 100) / 100);
const fmtInt = v => v.toLocaleString('en-AU');
const fmtDate = iso => { const [y, m, d] = iso.split('-').map(Number); return `${d} ${MONTHS[m - 1]} ${y}`; };

function render(days, { placeholder = false } = {}) {
  const W = 1200, H = 470;
  const doc = new Doc(W, H);
  const today = isoToday();
  const s = placeholder ? null : stats(days, today);
  const b = [];

  doc.defs.push(
    `<radialGradient id="tg" cx="1" cy="0" r="1"><stop offset="0" stop-color="${C.purple}" stop-opacity=".16"/><stop offset=".55" stop-color="${C.purple}" stop-opacity="0"/></radialGradient>`,
    `<linearGradient id="te" x1="0" x2="1"><stop offset="0" stop-color="${C.purple}" stop-opacity="0"/><stop offset=".5" stop-color="${C.purpleInk}" stop-opacity=".9"/><stop offset="1" stop-color="${C.purple}" stop-opacity="0"/></linearGradient>`,
    `<pattern id="tp" width="32" height="32" patternUnits="userSpaceOnUse"><path d="M32 0H0V32" fill="none" stroke="#fff" stroke-opacity=".035"/></pattern>`,
    `<linearGradient id="ts" x1="0" x2="1"><stop offset="0" stop-color="${C.cyan}" stop-opacity="0"/><stop offset=".8" stop-color="${C.cyan}" stop-opacity=".18"/><stop offset="1" stop-color="${C.cyan}" stop-opacity=".55"/></linearGradient>`,
  );
  b.push(`<rect x=".5" y=".5" width="${W - 1}" height="${H - 1}" rx="20" fill="${C.card}"/>`,
    `<rect x=".5" y=".5" width="${W - 1}" height="${H - 1}" rx="20" fill="url(#tg)"/>`,
    `<rect x=".5" y=".5" width="${W - 1}" height="${H - 1}" rx="20" fill="url(#tp)"/>`,
    `<rect x=".5" y=".5" width="${W - 1}" height="${H - 1}" rx="20" fill="none" stroke="${C.line}"/>`,
    `<rect x="40" y="0" width="${W - 80}" height="1.5" fill="url(#te)"/>`,
    `<path d="M16 32V16H32M${W - 32} 16H${W - 16}V32M${W - 16} ${H - 32}V${H - 16}H${W - 32}M32 ${H - 16}H16V${H - 32}" fill="none" stroke="${C.cyan}" stroke-width="1.5" opacity=".5"/>`);

  // top bar
  const live = placeholder ? 'SYNC PENDING' : 'LIVE FEED';
  const lw = doc.measure(live, 'j6', 12.5, 0.16);
  b.push(`<rect x="40" y="34" width="${n(lw + 46)}" height="30" rx="15" fill="${C.purpleSoft}" stroke="${C.purple}" stroke-opacity=".6"/>`,
    `<circle class="lv" cx="58" cy="49" r="4" fill="${placeholder ? C.subtle : C.cyan}"/>`,
    doc.text(live, 70, 53.5, 'j6', 12.5, { fill: C.purpleInk, ls: 0.16 }),
    doc.text('SOURCE  ·  GITHUB CONTRIBUTION CALENDAR', 40 + lw + 64, 53.5, 'j5', 12.5, { fill: C.subtle, ls: 0.14 }),
    doc.text(placeholder ? 'AWAITING FIRST RUN' : `SYNCED ${fmtDate(today)}  ·  AEST`, W - 40, 53.5, 'j5', 12.5, { fill: C.muted, anchor: 'end', ls: 0.14 }));

  // stat tiles
  const tiles = [
    ['CONTRIBUTIONS', s ? fmtInt(s.total) : '—', 'last 12 months'],
    ['CURRENT STREAK', s ? fmtInt(s.current) : '—', s && s.current === 1 ? 'day' : 'days'],
    ['LONGEST STREAK', s ? fmtInt(s.longest) : '—', s && s.longest === 1 ? 'day' : 'days'],
    ['ACTIVE DAYS', s ? fmtInt(s.active) : '—', s ? `of ${s.span}` : 'of 365'],
  ];
  const tw = (W - 80 - 3 * 16) / 4;
  tiles.forEach(([label, value, unit], i) => {
    const x = 40 + i * (tw + 16), y = 84;
    b.push(`<rect x="${n(x)}" y="${y}" width="${n(tw)}" height="108" rx="16" fill="${C.panel}" stroke="${C.line}"/>`,
      `<rect x="${n(x + 20)}" y="${y + 22}" width="3" height="14" rx="1.5" fill="${i === 0 ? C.cyan : C.purple}"/>`,
      doc.text(label, x + 32, y + 34, 'j6', 12.5, { fill: C.subtle, ls: 0.14 }));
    const vw = doc.measure(value, 's7', 40);
    b.push(doc.text(value, x + 20, y + 84, 's7', 40, { fill: C.ink }),
      doc.text(unit, x + 20 + vw + 10, y + 84, 'm6', 16, { fill: C.muted }));
  });

  // heatmap: 53 weeks ending this week, Sunday-first like GitHub
  const end = new Date(`${today}T00:00:00Z`);
  const start = new Date(end);
  start.setUTCDate(start.getUTCDate() - end.getUTCDay() - 52 * 7);
  const counts = new Map(days.map(d => [d.date, d.count]));
  const hx = 96, hy = 246, pitch = 19.6, cell = 15.5;
  const cells = [], months = [];
  let lastMonth = -1;
  for (let wk = 0; wk < 53; wk++) {
    for (let dow = 0; dow < 7; dow++) {
      const dt = new Date(start);
      dt.setUTCDate(start.getUTCDate() + wk * 7 + dow);
      const iso = dt.toISOString().slice(0, 10);
      if (iso > today) continue;
      if (dow === 0 && dt.getUTCMonth() !== lastMonth && wk < 52) {
        lastMonth = dt.getUTCMonth();
        if (wk > 0 || dt.getUTCDate() < 8) months.push([wk, MONTHS[lastMonth]]);
      }
      const c = counts.get(iso) || 0;
      const lvl = !s || !c ? 0 : c <= s.cuts[0] ? 1 : c <= s.cuts[1] ? 2 : c <= s.cuts[2] ? 3 : 4;
      cells.push(`<rect x="${n(hx + wk * pitch)}" y="${n(hy + dow * pitch)}" width="${cell}" height="${cell}" rx="4" fill="${LEVELS[lvl]}"${lvl === 4 ? ' class="hot"' : ''}/>`);
    }
  }
  b.push(...months.map(([wk, m]) => doc.text(m, hx + wk * pitch, hy - 12, 'j5', 12, { fill: C.subtle, ls: 0.1 })));
  b.push(...[['Mon', 1], ['Wed', 3], ['Fri', 5]].map(([d, i]) => doc.text(d, hx - 14, hy + i * pitch + 12, 'j5', 12, { fill: C.subtle, anchor: 'end' })));
  b.push(`<g>${cells.join('')}</g>`);
  const gridW = 53 * pitch;
  doc.defs.push(`<clipPath id="hc"><rect x="${hx - 4}" y="${hy - 4}" width="${n(gridW + 4)}" height="${n(7 * pitch + 4)}"/></clipPath>`);
  b.push(`<g clip-path="url(#hc)"><rect class="scan" style="--run:${n(gridW + 120)}px" x="${hx - 120}" y="${hy - 4}" width="120" height="${n(7 * pitch + 4)}" fill="url(#ts)"/></g>`);

  if (placeholder) {
    const msg = 'First sync runs when this lands on main, then daily via GitHub Actions';
    const mw = doc.measure(msg, 'm6', 16);
    b.push(`<rect x="${n(W / 2 - mw / 2 - 26)}" y="${n(hy + 3.5 * pitch - 22)}" width="${n(mw + 52)}" height="44" rx="22" fill="${C.panel}" stroke="${C.purple}" stroke-opacity=".6"/>`,
      doc.text(msg, W / 2, hy + 3.5 * pitch + 6, 'm6', 16, { fill: C.ink, anchor: 'middle' }));
  }

  // footer line
  const fy = H - 42;
  const facts = s && s.total
    ? [`PEAK DAY  ${fmtDate(s.peak.date)}  ·  ${fmtInt(s.peak.count)} CONTRIBUTIONS`, `MOST ACTIVE ON ${DAYS[s.topDay].toUpperCase()}`]
    : ['NO DATA YET'];
  b.push(doc.text(facts.join('     /     '), 40, fy + 4, 'j5', 12.5, { fill: C.muted, ls: 0.12 }));
  let lx = W - 40;
  const more = doc.measure('MORE', 'j5', 12, 0.1);
  b.push(doc.text('MORE', lx, fy + 4, 'j5', 12, { fill: C.subtle, anchor: 'end', ls: 0.1 }));
  lx -= more + 10 + 5 * 18;
  LEVELS.forEach((col, i) => b.push(`<rect x="${n(lx + i * 18)}" y="${fy - 8}" width="14" height="14" rx="4" fill="${col}"/>`));
  b.push(doc.text('LESS', lx - 10, fy + 4, 'j5', 12, { fill: C.subtle, anchor: 'end', ls: 0.1 }));

  const title = placeholder ? 'Development telemetry: awaiting first sync'
    : `Development telemetry: ${s.total} contributions in the last year, current streak ${s.current} days, longest streak ${s.longest} days, active on ${s.active} days.`;
  const css = `.lv{animation:lv 2.4s ease-in-out infinite}@keyframes lv{50%{opacity:.3}}`
    + `.scan{animation:sc 7s linear infinite}@keyframes sc{from{transform:translateX(0)}to{transform:translateX(var(--run))}}`
    + `.hot{animation:ht 3.6s ease-in-out infinite}@keyframes ht{50%{opacity:.7}}`
    + `@media (prefers-reduced-motion: reduce){*{animation:none!important}}`;
  return `<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 ${W} ${H}" width="${W}" height="${H}" role="img" aria-labelledby="t">`
    + `<title id="t">${title}</title><style>${css}</style><defs>${doc.defs.join('')}</defs>${b.join('')}</svg>`;
}

const placeholder = args.includes('--placeholder');
const days = placeholder ? [] : await loadDays();
if (!placeholder && days.length < 300) throw new Error(`expected a year of data, got ${days.length} days`);
fs.writeFileSync(OUT, render(days, { placeholder }));
console.log(`wrote ${OUT}${placeholder ? ' (placeholder)' : ` from ${days.length} days`}`);
